// A shared object plays the role of one memory cell at a fixed address.
const cell = { data: 100 };

// Both a and b hold the SAME address (reference to the same object).
let a = cell;
let b = cell;

// Mutate through a; b sees it, because both point at the same cell.
a.data = 71;
console.log('after a.data = 71 -> b.data is', b.data); // 71: aliasing

// A plain value is copied, not shared. x and y hold separate values.
let x = 5;
let y = x;
x = 12;
console.log('after x = 12 -> y is', y); // 5: independent copies
